// mock dom clean

global.Image = class {
  constructor() {
    this.src = '';
    this.complete = true;
    this.naturalWidth = 100;
  }
};
global.window = {
  addEventListener: () => {},
  devicePixelRatio: 2,
  AudioContext: class {
    createOscillator() { return { type: '', frequency: { setValueAtTime: ()=>{}, exponentialRampToValueAtTime: ()=>{}, linearRampToValueAtTime: ()=>{} }, connect: ()=>{}, start: ()=>{}, stop: ()=>{} }; }
    createGain() { return { gain: { setValueAtTime: ()=>{}, linearRampToValueAtTime: ()=>{}, exponentialRampToValueAtTime: ()=>{} }, connect: ()=>{} }; }
    createBuffer() { return { getChannelData: () => new Float32Array(100) }; }
    createBufferSource() { return { connect: ()=>{}, start: ()=>{} }; }
    createBiquadFilter() { return { frequency: { setValueAtTime: ()=>{}, exponentialRampToValueAtTime: ()=>{} }, connect: ()=>{} }; }
    createStereoPanner() { return { pan: { setValueAtTime: ()=>{} }, connect: ()=>{} }; }
  }
};
global.document = {
  body: { appendChild: ()=>{} },
  getElementById: (id) => ({
    style: {},
    classList: { add: ()=>{}, remove: ()=>{} },
    appendChild: ()=>{},
    after: ()=>{},
    addEventListener: ()=>{},
    getBoundingClientRect: () => ({ width: 400, height: 260, left: 0, top: 0 }),
    getContext: () => ({
      fillRect: ()=>{}, strokeRect: ()=>{}, fillText: ()=>{}, stroke: ()=>{}, fill: ()=>{}, beginPath: ()=>{}, moveTo: ()=>{}, lineTo: ()=>{}, arc: ()=>{}, ellipse: ()=>{}, clearRect: ()=>{}, save: ()=>{}, restore: ()=>{}, translate: ()=>{}, scale: ()=>{}, rotate: ()=>{}, quadraticCurveTo: ()=>{}, clip: ()=>{}, drawImage: ()=>{}
    }),
    toDataURL: () => 'data:image/png;base64,mock',
    innerHTML: '',
    hidden: false,
    remove: ()=>{}
  }),
  querySelector: () => ({ style: {}, classList: { add: ()=>{}, remove: ()=>{} }, after: ()=>{}, appendChild: ()=>{} }),
  querySelectorAll: () => [],
  createElement: () => ({ style: {}, classList: { add: ()=>{} }, appendChild: ()=>{}, remove: ()=>{}, addEventListener: ()=>{} })
};
global.localStorage = { getItem: () => null, setItem: () => {}, removeItem: () => {} };
global.performance = { now: () => Date.now() };

// 《促织》移动端全维终极纯净打包版
// 游戏内置水墨工笔画高质资源库\nexport const imageAssets = {\n  "actor_bailiff_officer": "data:image/jpeg;base64,",\n  "actor_cheng_ming": "data:image/jpeg;base64,",\n  "actor_son_child": "data:image/jpeg;base64,",\n  "actor_wife_woman": "data:image/jpeg;base64,",\n  "bg_cottage_interior": "data:image/jpeg;base64,",\n  "bg_desolate_well": "data:image/jpeg;base64,",\n  "bg_imperial_palace": "data:image/jpeg;base64,",\n  "bg_ruins_cottage": "data:image/jpeg;base64,",\n  "bg_temple_night": "data:image/jpeg;base64,",\n  "illustration_cricket_god": "data:image/jpeg;base64,",\n  "illustration_rooster": "data:image/jpeg;base64,",\n};\n
// Web Audio API 原生程序化音效合成器 v4（听觉黑洞＋二周目童声幽音＋3D立体声＋触觉引擎）
class SoundEngine {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.isSecondPlaythrough = false;
  }

  init() {
    if (this.ctx) return;
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (AudioCtx) {
      this.ctx = new AudioCtx();
    }
  }

  resume() {
    this.init();
    if (this.ctx && this.ctx.state === "suspended") {
      this.ctx.resume();
    }
  }

  toggle() {
    this.enabled = !this.enabled;
    return this.enabled;
  }

  vibrate(pattern) {
    if (!this.enabled) return;
    try {
      if (typeof navigator !== "undefined" && navigator.vibrate) {
        navigator.vibrate(pattern);
      }
    } catch (e) {}
  }

  playSpatialChirp(pan = 0, distFactor = 0.5) {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const carrier = this.ctx.createOscillator();
    const modulator = this.ctx.createOscillator();
    const modGain = this.ctx.createGain();
    const masterGain = this.ctx.createGain();

    const vol = Math.max(0.08, 0.45 * (1.0 - distFactor * 0.8));
    const duration = 0.16 + (1.0 - distFactor) * 0.1;

    carrier.type = "sine";
    carrier.frequency.setValueAtTime(4500, now);
    carrier.frequency.exponentialRampToValueAtTime(4100, now + duration);

    modulator.type = "triangle";
    modulator.frequency.setValueAtTime(60, now);

    modGain.gain.setValueAtTime(1100, now);
    modulator.connect(modGain);
    modGain.connect(carrier.frequency);

    masterGain.gain.setValueAtTime(0, now);
    masterGain.gain.linearRampToValueAtTime(vol, now + 0.02);
    masterGain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    carrier.connect(masterGain);

    if (this.ctx.createStereoPanner) {
      const panner = this.ctx.createStereoPanner();
      panner.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), now);
      masterGain.connect(panner);
      panner.connect(this.ctx.destination);
    } else {
      masterGain.connect(this.ctx.destination);
    }

    carrier.start(now);
    modulator.start(now);
    carrier.stop(now + duration);
    modulator.stop(now + duration);
  }

  playChildHumming(pan = 0, distFactor = 0.5) {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    const filter = this.ctx.createBiquadFilter();

    osc.type = "sine";
    osc.frequency.setValueAtTime(330, now);
    osc.frequency.linearRampToValueAtTime(392, now + 0.3);
    osc.frequency.linearRampToValueAtTime(330, now + 0.6);

    filter.type = "lowpass";
    filter.frequency.setValueAtTime(650, now);

    const vol = Math.max(0.02, 0.12 * (1.0 - distFactor * 0.7));
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(vol, now + 0.1);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.65);

    osc.connect(filter);
    filter.connect(gain);

    if (this.ctx.createStereoPanner) {
      const panner = this.ctx.createStereoPanner();
      panner.pan.setValueAtTime(Math.max(-1, Math.min(1, pan)), now);
      gain.connect(panner);
      panner.connect(this.ctx.destination);
    } else {
      gain.connect(this.ctx.destination);
    }

    osc.start(now);
    osc.stop(now + 0.65);
  }

  playChirp(duration = 0.22, volume = 0.35) {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const carrier = this.ctx.createOscillator();
    const modulator = this.ctx.createOscillator();
    const modGain = this.ctx.createGain();
    const masterGain = this.ctx.createGain();

    carrier.type = "sine";
    carrier.frequency.setValueAtTime(4500, now);
    carrier.frequency.exponentialRampToValueAtTime(4100, now + duration);

    modulator.type = "triangle";
    modulator.frequency.setValueAtTime(60, now);

    modGain.gain.setValueAtTime(1100, now);
    modulator.connect(modGain);
    modGain.connect(carrier.frequency);

    masterGain.gain.setValueAtTime(0, now);
    masterGain.gain.linearRampToValueAtTime(volume, now + 0.02);
    masterGain.gain.exponentialRampToValueAtTime(0.001, now + duration);

    carrier.connect(masterGain);
    masterGain.connect(this.ctx.destination);

    if (this.isSecondPlaythrough) {
      const breath = this.ctx.createOscillator();
      const bGain = this.ctx.createGain();
      breath.type = "sine";
      breath.frequency.setValueAtTime(560, now);
      bGain.gain.setValueAtTime(0.04, now);
      bGain.gain.exponentialRampToValueAtTime(0.0001, now + duration);
      breath.connect(bGain);
      bGain.connect(this.ctx.destination);
      breath.start(now);
      breath.stop(now + duration);
    }

    carrier.start(now);
    modulator.start(now);
    carrier.stop(now + duration);
    modulator.stop(now + duration);
  }

  playBurstChirps(count = 3) {
    if (!this.enabled) return;
    for (let i = 0; i < count; i++) {
      setTimeout(() => this.playChirp(0.16, 0.3), i * 110);
    }
  }

  playCaneHit() {
    this.vibrate(120);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "triangle";
    osc.frequency.setValueAtTime(130, now);
    osc.frequency.exponentialRampToValueAtTime(25, now + 0.35);

    const bufferSize = this.ctx.sampleRate * 0.15;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      output[i] = Math.random() * 2 - 1;
    }
    const whiteNoise = this.ctx.createBufferSource();
    whiteNoise.buffer = noiseBuffer;

    const filter = this.ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.setValueAtTime(400, now);
    filter.frequency.exponentialRampToValueAtTime(70, now + 0.2);

    const noiseGain = this.ctx.createGain();
    noiseGain.gain.setValueAtTime(0.65, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.01, now + 0.2);

    whiteNoise.connect(filter);
    filter.connect(noiseGain);
    noiseGain.connect(this.ctx.destination);

    gain.gain.setValueAtTime(0.75, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    whiteNoise.start(now);
    osc.start(now);
    osc.stop(now + 0.35);
  }

  playStrawTickle() {
    this.vibrate(15);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "sine";
    osc.frequency.setValueAtTime(700, now);
    osc.frequency.linearRampToValueAtTime(1500, now + 0.1);

    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.14, now + 0.03);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.1);
  }

  playBite() {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "square";
    osc.frequency.setValueAtTime(340, now);
    osc.frequency.exponentialRampToValueAtTime(50, now + 0.09);

    gain.gain.setValueAtTime(0.35, now);
    gain.gain.exponentialRampToValueAtTime(0.01, now + 0.09);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.09);
  }

  playParry() {
    this.vibrate(35);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "sine";
    osc.frequency.setValueAtTime(1050, now);
    osc.frequency.exponentialRampToValueAtTime(1600, now + 0.22);

    gain.gain.setValueAtTime(0.25, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.22);
  }

  playCriticalHitHole() {
    this.vibrate([50, 40, 110]);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const bass = this.ctx.createOscillator();
    const bGain = this.ctx.createGain();
    bass.type = "triangle";
    bass.frequency.setValueAtTime(120, now);
    bass.frequency.exponentialRampToValueAtTime(20, now + 0.1);
    bGain.gain.setValueAtTime(0.7, now);
    bGain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
    bass.connect(bGain);
    bGain.connect(this.ctx.destination);
    bass.start(now);
    bass.stop(now + 0.1);

    const whisper = this.ctx.createOscillator();
    const wGain = this.ctx.createGain();
    whisper.type = "sine";
    whisper.frequency.setValueAtTime(440, now + 0.03);
    whisper.frequency.linearRampToValueAtTime(392, now + 0.12);
    wGain.gain.setValueAtTime(0, now);
    wGain.gain.setValueAtTime(0.08, now + 0.03);
    wGain.gain.exponentialRampToValueAtTime(0.0001, now + 0.15);
    whisper.connect(wGain);
    wGain.connect(this.ctx.destination);
    whisper.start(now + 0.02);
    whisper.stop(now + 0.15);
  }

  playQinNote(pitch = 440) {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "triangle";
    osc.frequency.setValueAtTime(pitch, now);

    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.3, now + 0.04);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 1.8);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 1.8);
  }

  playQinDanceStep(step = 0) {
    this.vibrate(25);
    const scale = [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33];
    const pitch = scale[step % scale.length];
    this.playQinNote(pitch);
  }

  playPaperFlip() {
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "sine";
    osc.frequency.setValueAtTime(200, now);
    osc.frequency.exponentialRampToValueAtTime(35, now + 0.07);

    gain.gain.setValueAtTime(0.06, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.07);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.07);
  }

  playInkBleed() {
    this.vibrate([30, 40, 160]);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "triangle";
    osc.frequency.setValueAtTime(85, now);
    osc.frequency.exponentialRampToValueAtTime(18, now + 0.5);

    gain.gain.setValueAtTime(0.85, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.5);
  }

  playRoosterSquawk() {
    this.vibrate([60, 40, 80]);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;

    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();

    osc.type = "sawtooth";
    osc.frequency.setValueAtTime(680, now);
    osc.linearRampToValueAtTime(300, now + 0.35);

    gain.gain.setValueAtTime(0.4, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.45);

    osc.connect(gain);
    gain.connect(this.ctx.destination);

    osc.start(now);
    osc.stop(now + 0.45);
  }

  playLidOpen() {
    this.vibrate(25);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(320, now);
    osc.frequency.linearRampToValueAtTime(180, now + 0.18);
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(0.18, now + 0.04);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(now);
    osc.stop(now + 0.18);
  }

  playWaterDrop() {
    this.vibrate([20, 30, 40]);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(1400, now);
    osc.frequency.exponentialRampToValueAtTime(500, now + 0.25);
    gain.gain.setValueAtTime(0.35, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.35);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(now);
    osc.stop(now + 0.35);
  }

  playHeartbeat() {
    this.vibrate([40, 60, 40]);
    if (!this.enabled) return;
    this.resume();
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = "triangle";
    osc.frequency.setValueAtTime(65, now);
    osc.frequency.exponentialRampToValueAtTime(35, now + 0.12);
    gain.gain.setValueAtTime(0.4, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + 0.12);
    osc.connect(gain);
    gain.connect(this.ctx.destination);
    osc.start(now);
    osc.stop(now + 0.12);
  }
}

const sound = new SoundEngine();
// 本地持久化与虫谱解锁状态
const STORAGE_KEY_PLAYTHROUGH = "cuzhi_playthrough_count";
const STORAGE_KEY_RECORDS = "cuzhi_battle_records";
const STORAGE_KEY_MANUAL = "cuzhi_unlocked_manual";

const storage = {
  getPlaythroughCount() {
    try {
      return parseInt(localStorage.getItem(STORAGE_KEY_PLAYTHROUGH) || "0", 10);
    } catch {
      return 0;
    }
  },

  incrementPlaythrough() {
    try {
      const current = this.getPlaythroughCount();
      localStorage.setItem(STORAGE_KEY_PLAYTHROUGH, (current + 1).toString());
      return current + 1;
    } catch {
      return 1;
    }
  },

  isSecondPlaythroughOrMore() {
    return this.getPlaythroughCount() >= 1;
  },

  unlockManualItem(id) {
    try {
      const list = this.getUnlockedManual();
      if (!list.includes(id)) {
        list.push(id);
        localStorage.setItem(STORAGE_KEY_MANUAL, JSON.stringify(list));
      }
    } catch (e) {
      console.warn("Manual save failed:", e);
    }
  },

  getUnlockedManual() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY_MANUAL) || '["crab_green"]');
    } catch {
      return ["crab_green"];
    }
  }
};
// 全局游戏状态机与对战统计模型

class GameState {
  constructor() {
    this.currentBeat = 1;
    this.scriptIndex = 0;
    this.cricketName = "青项金翅";
    this.smallCricketName = "小梅花";
    
    // 显性表：得意与家运 (0 ~ 100)
    this.fortune = 0;
    this.fortuneLabel = "大祸临头";
    this.fortuneSubtext = "摊派催逼 · 杖责五十";

    // 战绩实录清单
    this.battleLog = [];

    // 对战综合统计（用于生成千人千面藏书票印章）
    this.stats = {
      totalParries: 0,
      totalStrikes: 0,
      sufferedDefeats: 0,
      perfectDance: true,
      strawTeaseCount: 0
    };

    // 周目状态
    this.isSecondPlaythrough = storage.isSecondPlaythroughOrMore();
  }

  setBeat(beat) {
    this.currentBeat = beat;
    this.scriptIndex = 0;
  }

  updateFortune(value, label, subtext) {
    this.fortune = Math.max(0, Math.min(100, value));
    if (label) this.fortuneLabel = label;
    if (subtext) this.fortuneSubtext = subtext;
  }

  addBattleRecord(record) {
    this.battleLog.push(record);
  }

  // 计算千人千面藏书票印鉴评价
  getSealTitle() {
    if (this.stats.sufferedDefeats === 0 && this.stats.totalParries >= 3) {
      return { title: "灵犀绝杀", sub: "破尽敌芒 · 算无遗策" };
    } else if (this.stats.sufferedDefeats === 0) {
      return { title: "百战无伤", sub: "轻捷迅勇 · 一往直前" };
    } else if (this.stats.sufferedDefeats > 0) {
      return { title: "险胜入宫", sub: "如履薄冰 · 死里求生" };
    }
    return { title: "天子近臣", sub: "应节羽舞 · 恩荫子孙" };
  }

  reset() {
    this.currentBeat = 1;
    this.scriptIndex = 0;
    this.cricketName = "青项金翅";
    this.smallCricketName = "小梅花";
    this.fortune = 0;
    this.fortuneLabel = "大祸临头";
    this.fortuneSubtext = "摊派催逼 · 杖责五十";
    this.battleLog = [];
    this.stats = {
      totalParries: 0,
      totalStrikes: 0,
      sufferedDefeats: 0,
      perfectDance: true,
      strawTeaseCount: 0
    };
    this.isSecondPlaythrough = storage.isSecondPlaythroughOrMore();
  }
}

const state = new GameState();
// 尘土粒子与墨点视觉特效
class ParticleEngine {
  constructor(container) {
    this.container = container;
    this.particles = [];
    this.isRunning = false;
  }

  start() {
    if (this.isRunning) return;
    this.isRunning = true;
    this.createAmbientDust();
  }

  createAmbientDust() {
    if (!this.container) return;
    this.container.innerHTML = '';
    const count = 18;
    for (let i = 0; i < count; i++) {
      const p = document.createElement('div');
      p.className = 'dust-speck';
      p.style.position = 'absolute';
      p.style.width = (Math.random() * 3 + 1) + 'px';
      p.style.height = p.style.width;
      p.style.backgroundColor = 'rgba(230, 223, 206, ' + (Math.random() * 0.3 + 0.1) + ')';
      p.style.borderRadius = '50%';
      p.style.left = (Math.random() * 100) + '%';
      p.style.top = (Math.random() * 100) + '%';
      p.style.pointerEvents = 'none';
      p.style.filter = 'blur(1px)';
      p.style.animation = 'dustFloat ' + (Math.random() * 6 + 6) + 's infinite ease-in-out ' + (Math.random() * 5) + 's';
      this.container.appendChild(p);
    }
  }

  spawnHitSparks(x, y, text = '破！') {
    const parent = document.getElementById('battle-fx');
    if (!parent) return;
    const spark = document.createElement('div');
    spark.className = 'hit-spark';
    spark.innerText = text;
    spark.style.left = x + 'px';
    spark.style.top = y + 'px';
    parent.appendChild(spark);
    setTimeout(() => spark.remove(), 700);
  }

  spawnMusicNote(x, y, glyph = '♪') {
    const parent = document.getElementById('dance-notes');
    if (!parent) return;
    parent.hidden = false;
    const note = document.createElement('div');
    note.className = 'music-glyph';
    note.innerText = glyph;
    note.style.left = x + 'px';
    note.style.top = y + 'px';
    parent.appendChild(note);
    setTimeout(() => note.remove(), 2000);
  }
}
