// 拍②：古庙草丛寻声捕虫小玩法（含 3D 空间立体声与二周目幽音）

class CatchGame {
  constructor(container, onComplete) {
    this.container = container;
    this.onComplete = onComplete;
    this.field = document.getElementById("catch-field");
    this.hintEl = document.querySelector(".catch-hint");
    this.targetX = 0;
    this.targetY = 0;
    this.attempts = 0;
    this.chirpTimer = null;
    this.width = 340;
    this.height = 220;
  }

  start() {
    if (!this.container || !this.field) return;
    this.container.hidden = false;
    this.field.innerHTML = "";
    this.attempts = 0;

    for (let i = 0; i < 9; i++) {
      const spot = document.createElement("div");
      spot.className = "grass-spot";
      spot.style.left = (10 + (i % 3) * 35 + Math.random() * 8) + "%";
      spot.style.top = (15 + Math.floor(i / 3) * 30 + Math.random() * 8) + "%";
      spot.innerText = "艸";
      this.field.appendChild(spot);
    }

    const rect = this.field.getBoundingClientRect();
    this.width = rect.width || 340;
    this.height = rect.height || 220;
    this.targetX = Math.floor(Math.random() * (this.width - 80)) + 40;
    this.targetY = Math.floor(Math.random() * (this.height - 80)) + 40;

    if (this.hintEl) this.hintEl.innerText = "草丛窸窣 · 听辨方位寻声覆之（建议佩戴耳机）";

    const initialPan = (this.targetX - this.width / 2) / (this.width / 2);
    sound.playSpatialChirp(initialPan, 0.7);
    if (storage.isSecondPlaythroughOrMore()) {
      sound.playChildHumming(initialPan, 0.7);
    }

    this.chirpTimer = setInterval(() => {
      sound.playSpatialChirp(initialPan, 0.65);
      if (storage.isSecondPlaythroughOrMore()) {
        sound.playChildHumming(initialPan, 0.65);
      }
    }, 2400);

    this.field.onclick = (e) => {
      const fRect = this.field.getBoundingClientRect();
      const clickX = e.clientX - fRect.left;
      const clickY = e.clientY - fRect.top;

      const dx = clickX - this.targetX;
      const dy = clickY - this.targetY;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const maxDist = Math.sqrt(this.width * this.width + this.height * this.height) || 400;
      const distFactor = Math.min(1.0, dist / maxDist);

      const currentPan = (this.targetX - clickX) / (this.width / 2);
      this.attempts++;
      sound.playSpatialChirp(currentPan, distFactor);
      if (storage.isSecondPlaythroughOrMore()) {
        sound.playChildHumming(currentPan, distFactor);
      }

      const ripple = document.createElement("div");
      ripple.className = "hit-spark";
      ripple.innerText = dist < 65 ? "急！" : "沙…";
      ripple.style.left = clickX + "px";
      ripple.style.top = clickY + "px";
      this.field.appendChild(ripple);
      setTimeout(() => ripple.remove(), 600);

      if (dist < 60 || this.attempts >= 4) {
        this.successCatch();
      } else if (dist < 130) {
        if (this.hintEl) this.hintEl.innerText = "鸣声转急！近在咫尺！";
      } else {
        const dir = dx > 0 ? "左" : "右";
        if (this.hintEl) this.hintEl.innerText = `微声在${dir}侧草际……`;
      }
    };
  }

  successCatch() {
    clearInterval(this.chirpTimer);
    this.field.onclick = null;
    sound.playBurstChirps(4);
    sound.vibrate([40, 50, 100]);

    if (this.hintEl) this.hintEl.innerText = "扣得神虫！青项金翅！";

    const targetNode = document.createElement("div");
    targetNode.className = "catch-target-node";
    targetNode.style.left = (this.targetX - 22) + "px";
    targetNode.style.top = (this.targetY - 22) + "px";
    targetNode.style.transform = "scale(1.5)";
    targetNode.style.background = "rgba(229, 185, 92, 0.9)";
    targetNode.style.boxShadow = "0 0 25px #e5b95c";
    this.field.appendChild(targetNode);

    setTimeout(() => {
      this.container.hidden = true;
      if (this.onComplete) this.onComplete();
    }, 1200);
  }

  cleanup() {
    if (this.chirpTimer) clearInterval(this.chirpTimer);
    if (this.container) this.container.hidden = true;
  }
}
// 拍⑤：核心斗虫引擎 v11（空间防融重叠＋直跃鸡冠高空绝杀＋流畅不卡关机制）

class BattleGame {
  constructor(options) {
    this.canvas = document.getElementById("battle-canvas");
    this.ctx = this.canvas ? this.canvas.getContext("2d") : null;
    this.onVictory = options.onVictory;
    this.onDefeat = options.onDefeat;
    this.particleEngine = options.particleEngine;

    this.currentOpponentIndex = 0;
    this.opponent = null;

    // 玩家数据
    this.playerHp = 100;
    this.maxPlayerHp = 100;
    this.momentum = 0;
    this.parryUntil = 0;
    this.parryCooldownUntil = 0;
    this.attackUntil = 0;
    this.attackCooldownUntil = 0;
    this.isTeased = false;
    this.isVictoryPosture = false;
    this.playerFlinchUntil = 0;

    // 敌方数据
    this.enemyHp = 100;
    this.maxEnemyHp = 100;
    this.enemyState = "idle"; // idle, windup, attack, stunned, dead
    this.enemyFlinchUntil = 0;
    this.enemyActionTimer = null;

    // 琴舞
    this.danceSteps = 0;
    this.maxDanceSteps = 5;

    // 触摸手势
    this.touchStraw = { active: false, x: 0, y: 0 };
    this.touchStartPos = { x: 0, y: 0 };
    this.isDragging = false;
    this.lastTapTime = 0;

    // 动画
    this.danmuTimer = null;
    this.tellCycle = 0;
    this.animFrame = null;
    this.isRunning = false;
    this.hitstopUntil = 0;
    this.width = 600;
    this.height = 300;

    this.roosterImg = new Image();
    this.roosterImg.src = (typeof imageAssets !== "undefined" && imageAssets.illustration_rooster) || "data:image/jpeg;base64,";

    this.crowdComments = [
      "好虫！", "神了！", "这瘦虫竟如此了得！", "好一身梅花翅！",
      "咬它！", "直跃鸡冠！", "好利害的牙口！", "真乃神虫也！"
    ];

    this.secondPlayComments = [
      "……不过是一只虫罢了。", "天下人命，不如宫中一戏。",
      "万金买一笑，谁管瓦底魂。", "好狠的局……"
    ];

    this.bindEvents();
    this.bindTouchGestures();
    this.resizeCanvas();
    window.addEventListener("resize", () => this.resizeCanvas());
  }

  resizeCanvas() {
    if (!this.canvas) return;
    const bowl = document.getElementById("arena-bowl");
    if (!bowl) return;
    const rect = bowl.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    this.width = rect.width || 600;
    this.height = rect.height || 300;
    this.canvas.width = this.width * dpr;
    this.canvas.height = this.height * dpr;
    if (this.ctx) {
      this.ctx.resetTransform?.();
      this.ctx.scale(dpr, dpr);
    }
  }

  bindEvents() {
    const btnTease = document.getElementById("btn-tease");
    const btnParry = document.getElementById("btn-parry");
    const btnStrike = document.getElementById("btn-strike");

    if (btnTease) btnTease.onclick = (e) => { e.stopPropagation(); this.handleTease(); };
    if (btnParry) btnParry.onclick = (e) => { e.stopPropagation(); this.handleParry(); };
    if (btnStrike) btnStrike.onclick = (e) => { e.stopPropagation(); this.handleStrike(); };

    window.addEventListener("keydown", (e) => {
      if (!this.isRunning) return;
      if (e.key === "j" || e.key === "J") this.handleTease();
      if (e.key === "k" || e.key === "K") this.handleParry();
      if (e.key === "l" || e.key === "L") this.handleStrike();
      if (e.key === " " && this.opponent?.isPalaceDance) this.handleDanceStep();
    });
  }

  bindTouchGestures() {
    const bowl = document.getElementById("arena-bowl");
    if (!bowl) return;

    const onStart = (clientX, clientY) => {
      if (!this.isRunning) return;
      const rect = bowl.getBoundingClientRect();
      this.touchStartPos = { x: clientX - rect.left, y: clientY - rect.top };
      this.touchStraw.active = true;
      this.touchStraw.x = this.touchStartPos.x;
      this.touchStraw.y = this.touchStartPos.y;
      this.isDragging = false;
    };

    const onMove = (clientX, clientY) => {
      if (!this.isRunning || !this.touchStraw.active) return;
      const rect = bowl.getBoundingClientRect();
      const curX = clientX - rect.left;
      const curY = clientY - rect.top;

      const moveDist = Math.hypot(curX - this.touchStartPos.x, curY - this.touchStartPos.y);
      if (moveDist > 10) this.isDragging = true;

      this.touchStraw.x = curX;
      this.touchStraw.y = curY;

      // 挑逗玩家促织蓄力
      const px = this.width * 0.22;
      const py = this.height * 0.58;
      const dist = Math.hypot(curX - px, curY - py);

      if (dist < 55 && !this.isAttacking && !this.opponent?.isPalaceDance) {
        state.stats.strawTeaseCount++;
        this.momentum = Math.min(100, this.momentum + 4.0);
        this.isTeased = true;
        sound.playStrawTickle();
        this.updateHUD();
      }
    };

    const onEnd = (clientX, clientY) => {
      if (!this.isRunning) return;
      this.touchStraw.active = false;

      if (this.opponent?.isPalaceDance) {
        this.handleDanceStep();
        return;
      }

      if (!this.isDragging) {
        const now = performance.now();
        if (now - this.lastTapTime < 280) {
          this.handleStrike();
        } else {
          this.handleParry();
        }
        this.lastTapTime = now;
      }
    };

    bowl.addEventListener("touchstart", (e) => {
      if (e.touches.length > 0) onStart(e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });

    bowl.addEventListener("touchmove", (e) => {
      if (e.touches.length > 0) onMove(e.touches[0].clientX, e.touches[0].clientY);
    }, { passive: true });

    bowl.addEventListener("touchend", (e) => {
      if (e.changedTouches.length > 0) onEnd(e.changedTouches[0].clientX, e.changedTouches[0].clientY);
    });

    bowl.addEventListener("mousedown", (e) => onStart(e.clientX, e.clientY));
    bowl.addEventListener("mousemove", (e) => { if (e.buttons === 1) onMove(e.clientX, e.clientY); });
    bowl.addEventListener("mouseup", (e) => onEnd(e.clientX, e.clientY));
  }

  startMatch(opponentIndex = 0) {
    if (this.enemyActionTimer) clearTimeout(this.enemyActionTimer);
    this.currentOpponentIndex = opponentIndex;
    this.opponent = opponentsData[this.currentOpponentIndex];
    if (!this.opponent) return;

    storage.unlockManualItem(this.opponent.id);

    this.resizeCanvas();
    this.isRunning = true;
    this.isVictoryPosture = false;
    this.playerHp = 100;
    this.maxPlayerHp = 100;
    this.momentum = 0;
    this.isParrying = false;
    this.parryUntil = 0;
    this.parryCooldownUntil = 0;
    this.isAttacking = false;
    this.enemyHp = this.opponent.maxHp;
    this.maxEnemyHp = this.opponent.maxHp;
    this.enemyState = "idle";
    this.danceSteps = 0;

    const pName = document.getElementById("my-cricket-name");
    if (pName) pName.innerText = state.smallCricketName || "小梅花";

    this.setupControlsMode();
    this.updateHUD();
    sound.playBurstChirps(2);

    this.startDanmu();

    if (this.opponent.isPalaceDance) {
      sound.playQinDanceStep(0);
      const hint = document.getElementById("battle-hint-bar");
      if (hint) hint.innerText = "琴瑟和鸣 · 点按全屏随乐起舞！";
    } else {
      this.scheduleEnemyAction();
    }

    this.loop();
  }

  setupControlsMode() {
    const controls = document.getElementById("battle-controls");
    if (!controls) return;

    const isLateGame = this.currentOpponentIndex >= 2;
    const teaseSub = isLateGame ? "逼命向前" : "蓄势积力";

    if (this.opponent.isPalaceDance) {
      controls.innerHTML = `
        <button class="dance-control-btn" id="btn-dance" type="button">
          <span>闻琴起舞 · 击节振翅（轻点全屏）</span>
        </button>
      `;
      const btnDance = document.getElementById("btn-dance");
      if (btnDance) btnDance.onclick = (e) => { e.stopPropagation(); this.handleDanceStep(); };
    } else {
      controls.innerHTML = `
        <button class="battle-btn btn-tease" id="btn-tease" type="button">
          <span class="key-hint">划屏/J</span><strong>草丝挑逗</strong><small>${teaseSub}</small>
        </button>
        <button class="battle-btn btn-parry" id="btn-parry" type="button">
          <span class="key-hint">点屏/K</span><strong>侧身避咬</strong><small>破其锋芒</small>
        </button>
        <button class="battle-btn btn-strike" id="btn-strike" type="button">
          <span class="key-hint">双击/L</span><strong>疾进直前</strong><small>乘胜绝杀</small>
        </button>
      `;
      this.bindEvents();
    }
  }

  startDanmu() {
    if (this.danmuTimer) clearInterval(this.danmuTimer);
    const pool = (storage.isSecondPlaythroughOrMore() && Math.random() > 0.35) 
      ? this.secondPlayComments 
      : (this.opponent?.isPalaceDance ? ["圣上龙颜大悦！", "真奇虫也！", "百戏未有此妙！", "妙极！"] : this.crowdComments);

    this.danmuTimer = setInterval(() => {
      if (!this.isRunning) return;
      const fxLayer = document.getElementById("battle-fx");
      if (!fxLayer) return;

      const danmu = document.createElement("div");
      danmu.className = "danmu-comment";
      danmu.innerText = pool[Math.floor(Math.random() * pool.length)];
      danmu.style.top = (12 + Math.random() * 64) + "%";
      fxLayer.appendChild(danmu);

      setTimeout(() => danmu.remove(), 4000);
    }, 2600);
  }

  updateHUD() {
    const pFill = document.getElementById("my-energy-fill");
    const mFill = document.getElementById("my-momentum-fill");
    const eFill = document.getElementById("enemy-energy-fill");
    const vsBadge = document.getElementById("battle-vs-badge");
    const enemyName = document.getElementById("enemy-cricket-name");
    const enemyStatus = document.getElementById("enemy-status");
    const comboBadge = document.getElementById("combo-badge");

    if (pFill) pFill.style.width = Math.max(0, (this.playerHp / this.maxPlayerHp) * 100) + "%";
    
    const bowl = document.getElementById("arena-bowl");
    if (bowl) {
      if (this.playerHp <= 30 && this.playerHp > 0) {
        bowl.classList.add("desperation-state");
      } else {
        bowl.classList.remove("desperation-state");
      }
    }

    if (mFill) mFill.style.width = this.momentum + "%";
    if (eFill) eFill.style.width = Math.max(0, (this.enemyHp / this.maxEnemyHp) * 100) + "%";
    if (vsBadge) vsBadge.innerText = this.opponent.title.split(" · ")[0];
    if (enemyName) enemyName.innerText = this.opponent.name;

    if (comboBadge) {
      const stakes = [
        "赌注：一吊铜钱 vs 半斗米",
        "筹码：免役文书 补邑庠生",
        "重赏：赐金百两 骏马良田",
        "天赏：富埒世家 恩荫子孙"
      ];
      comboBadge.innerText = stakes[this.currentOpponentIndex] || "对赌进行中";
    }

    if (enemyStatus) {
      if (this.opponent.isPalaceDance) {
        enemyStatus.innerText = `御案弄乐 · 节拍 ${this.danceSteps}/${this.maxDanceSteps}`;
      } else if (this.enemyState === "windup") {
        enemyStatus.innerText = "【前摇破绽！】单点避咬！";
      } else if (this.enemyState === "stunned") {
        enemyStatus.innerText = "【大破僵直！】双击绝杀！";
      } else if (this.enemyState === "attack") {
        enemyStatus.innerText = "【扑咬攻来！】";
      } else {
        enemyStatus.innerText = "昂首对峙";
      }
    }
  }

  // 1. 草丝挑逗
  handleTease() {
    if (!this.isRunning || this.isAttacking) return;
    state.stats.strawTeaseCount++;
    sound.playStrawTickle();
    this.momentum = Math.min(100, this.momentum + 35);
    this.isTeased = true;
    sound.playChirp(0.16, 0.2);

    const straw = document.getElementById("straw-brush");
    if (straw) {
      straw.style.opacity = "1";
      straw.style.left = (this.width * 0.22) + "px";
      straw.style.top = (this.height * 0.55) + "px";
      setTimeout(() => { straw.style.opacity = "0"; }, 160);
    }

    if (this.particleEngine) {
      this.particleEngine.spawnHitSparks(this.width * 0.25, this.height * 0.45, "势起！");
    }
    this.updateHUD();
  }

  // 2. 侧身避咬（精准格挡窗口 280ms）
  handleParry() {
    const now = performance.now();
    if (!this.isRunning || now < this.parryCooldownUntil) return;

    this.isParrying = true;
    this.parryUntil = now + 280;
    this.parryCooldownUntil = now + 380;
    state.stats.totalParries++;
    sound.playParry();

    if (this.enemyState === "windup") {
      this.enemyState = "stunned";
      this.momentum = 100;
      sound.playBurstChirps(3);
      sound.vibrate([40, 60]);

      if (this.particleEngine) {
        this.particleEngine.spawnHitSparks(this.width * 0.72, this.height * 0.45, "大破其锋！");
      }
      const hint = document.getElementById("battle-hint-bar");
      if (hint) hint.innerText = "敌虫大破僵直！立即【双击/扑咬】绝杀！";

      setTimeout(() => {
        if (this.enemyState === "stunned") {
          this.enemyState = "idle";
          this.updateHUD();
          this.scheduleEnemyAction();
        }
      }, 1700);
    }

    this.updateHUD();
    setTimeout(() => { this.isParrying = false; }, 280);
  }

  // 3. 扑咬绝杀（进攻敌方 · 弧线跳跃打击＋100% 自动回落归位）
  handleStrike() {
    const now = performance.now();
    if (!this.isRunning || now < this.attackCooldownUntil) return;
    this.attackUntil = now + 360;
    this.attackCooldownUntil = now + 420;
    state.stats.totalStrikes++;

    const isCrit = this.momentum >= 70 || this.enemyState === "stunned";
    const dmg = isCrit ? (this.opponent.isSpecialRooster ? 58 : 45) : 22;

    if (isCrit) {
      this.hitstopUntil = now + 90;
      sound.playCriticalHitHole();
      const bowl = document.getElementById("arena-bowl");
      if (bowl) {
        bowl.classList.add("screen-shake");
        setTimeout(() => bowl.classList.remove("screen-shake"), 220);
      }
    } else {
      sound.playBite();
      sound.vibrate(30);
    }

    this.enemyFlinchUntil = now + 280;
    this.enemyHp = Math.max(0, this.enemyHp - dmg);
    this.momentum = 0;

    const hitLabel = this.opponent.isSpecialRooster ? (isCrit ? " 直跃鸡冠！" : " 扑啄！") : (isCrit ? " 绝杀！" : "");
    this.spawnCombatText(this.width * 0.72, this.height * 0.35, `-${dmg}` + hitLabel, isCrit ? "#e5b95c" : "#ffffff");

    if (this.opponent.isSpecialRooster) {
      sound.playRoosterSquawk();
      if (this.particleEngine) {
        this.particleEngine.spawnHitSparks(this.width * 0.72, this.height * 0.25, isCrit ? "啮其冠肉！" : "纵身！");
      }
    }

    this.updateHUD();

    if (this.enemyHp <= 0) {
      this.enemyState = "dead";
      this.isVictoryPosture = true;
      sound.playBurstChirps(4);
      setTimeout(() => this.handleMatchWin(), 900);
    }
  }

  spawnCombatText(x, y, text, color = "#a8382b") {
    const fxLayer = document.getElementById("battle-fx");
    if (!fxLayer) return;
    const txt = document.createElement("div");
    txt.className = "hit-spark";
    txt.innerText = text;
    txt.style.left = (x - 20) + "px";
    txt.style.top = (y - 30) + "px";
    txt.style.color = color;
    txt.style.textShadow = "0 0 10px rgba(0,0,0,0.8)";
    fxLayer.appendChild(txt);
    setTimeout(() => txt.remove(), 700);
  }

  // 4. 敌方攻击调度
  scheduleEnemyAction() {
    if (!this.isRunning || this.enemyHp <= 0 || this.opponent.isPalaceDance) return;
    if (this.enemyActionTimer) clearTimeout(this.enemyActionTimer);

    const delay = Math.random() * 800 + (this.opponent.speed > 1.2 ? 900 : 1300);

    this.enemyActionTimer = setTimeout(() => {
      if (!this.isRunning || this.enemyHp <= 0 || this.enemyState === "stunned" || this.opponent.isPalaceDance) return;

      if (this.enemyState === "idle") {
        this.enemyState = "windup";
        this.updateHUD();
        sound.playChirp(0.12, 0.25);

        this.enemyActionTimer = setTimeout(() => {
          if (this.enemyState === "windup") {
            this.enemyState = "attack";
            this.updateHUD();

            const now = performance.now();
            const parryActive = this.isParrying && (now <= this.parryUntil);

            if (!parryActive) {
              const incomingDmg = this.opponent.attackPower;
              this.playerHp = Math.max(0, this.playerHp - incomingDmg);
              this.playerFlinchUntil = performance.now() + 300;
              this.momentum = Math.max(0, this.momentum - 15);

              sound.playBite();
              sound.vibrate([50, 30, 60]);

              this.spawnCombatText(this.width * 0.22, this.height * 0.4, `-${incomingDmg}`, "#ff3b30");

              const bowl = document.getElementById("arena-bowl");
              if (bowl) {
                bowl.classList.add("screen-shake");
                setTimeout(() => bowl.classList.remove("screen-shake"), 180);
              }

              this.updateHUD();

              if (this.playerHp <= 0) {
                this.handleMatchDefeat();
                return;
              }
            } else {
              sound.playParry();
            }

            this.enemyActionTimer = setTimeout(() => {
              if (this.enemyState === "attack") {
                this.enemyState = "idle";
                this.updateHUD();
                this.scheduleEnemyAction();
              }
            }, 320);
          }
        }, this.opponent.windupDuration);
      } else {
        this.scheduleEnemyAction();
      }
    }, delay);
  }

  handleDanceStep() {
    if (!this.isRunning || !this.opponent.isPalaceDance) return;
    this.danceSteps++;
    sound.playQinDanceStep(this.danceSteps);
    sound.playBurstChirps(1);

    if (this.particleEngine) {
      const glyphs = ["♪", "羽", "徵", "角", "商", "宫"];
      this.particleEngine.spawnMusicNote(this.width * (0.35 + Math.random() * 0.3), this.height * 0.5, glyphs[this.danceSteps % glyphs.length]);
    }

    this.updateHUD();

    if (this.danceSteps >= this.maxDanceSteps) {
      this.handleMatchWin();
    }
  }

  // 战败彻底倒地急救（一键重整旗鼓）
  handleMatchDefeat() {
    this.isRunning = false;
    if (this.enemyActionTimer) clearTimeout(this.enemyActionTimer);
    state.stats.sufferedDefeats++;
    if (this.danmuTimer) clearInterval(this.danmuTimer);

    const bowl = document.getElementById("arena-bowl");
    if (bowl) bowl.classList.add("screen-shake");
    sound.vibrate([100, 50, 150]);

    setTimeout(() => {
      if (bowl) bowl.classList.remove("screen-shake");
      this.showEmergencyDefeatModal();
    }, 400);
  }

  showEmergencyDefeatModal() {
    let rescueModal = document.getElementById("rescue-modal");
    if (!rescueModal) {
      rescueModal = document.createElement("div");
      rescueModal.id = "rescue-modal";
      rescueModal.className = "rescue-modal";
      document.body.appendChild(rescueModal);
    }
    rescueModal.hidden = false;

    rescueModal.innerHTML = `
      <div class="rescue-box">
        <h4 style="color:#a8382b;">【 小虫负伤受挫 】</h4>
        <p>败于【${this.opponent.name}】之手。成名急取清露敷伤调理，誓不言败！</p>
        <button class="rescue-action-btn" id="btn-do-rescue" type="button" style="background:#2b5c3b;margin-top:8px;">【 咬牙再战 】</button>
      </div>
    `;

    const btn = document.getElementById("btn-do-rescue");
    btn.onclick = (ev) => {
      ev.stopPropagation();
      rescueModal.remove();
      if (this.onDefeat) {
        this.onDefeat(this.opponent, this.currentOpponentIndex);
      }
      this.startMatch(this.currentOpponentIndex);
    };
  }

  handleMatchWin() {
    this.isRunning = false;
    if (this.enemyActionTimer) clearTimeout(this.enemyActionTimer);
    if (this.danmuTimer) clearInterval(this.danmuTimer);
    sound.playBurstChirps(5);

    setTimeout(() => {
      if (this.onVictory) {
        this.onVictory(this.opponent, this.currentOpponentIndex);
      }
    }, 800);
  }

  loop() {
    if (!this.isRunning && !this.ctx) return;
    
    if (performance.now() >= this.hitstopUntil) {
      this.tellCycle += 0.03;
      this.render();
    }
    
    this.animFrame = requestAnimationFrame(() => this.loop());
  }

  render() {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const now = performance.now();
    ctx.clearRect(0, 0, this.width, this.height);

    // 斗草盆底阴影
    ctx.save();
    ctx.fillStyle = "rgba(18, 14, 10, 0.4)";
    ctx.beginPath();
    ctx.ellipse(this.width * 0.5, this.height * 0.78, this.width * 0.44, this.height * 0.16, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    if (storage.isSecondPlaythroughOrMore()) {
      this.drawChildShadowMetaphor(ctx);
    }

    // 敌方角色位置：待机 0.76，攻击向前冲至 0.52
    const isEnemyFlinching = now < this.enemyFlinchUntil;
    let ex = this.enemyState === "attack" ? this.width * 0.52 : (this.enemyState === "windup" ? this.width * 0.74 : this.width * 0.76);
    if (isEnemyFlinching) ex += 12;
    let ey = this.height * 0.58;

    // 绘制敌方角色（大公鸡或敌虫）
    this.drawOpponent(ctx, ex, ey, isEnemyFlinching);

    // 玩家小促织位置计算（时间戳驱动，绝无卡死可能）
    const isPlayerFlinching = now < this.playerFlinchUntil;
    const isParrying = now < this.parryUntil;
    const isAttacking = now < this.attackUntil;

    let basePx = isParrying ? this.width * 0.16 : this.width * 0.22;
    let basePy = this.height * 0.58;
    let px = basePx;
    let py = basePy;

    if (isAttacking) {
      // 0.0 -> 1.0 攻击进度
      const progress = 1.0 - Math.max(0, (this.attackUntil - now) / 360);
      // 抛物线高度：起跳 -> 达到顶峰 -> 回落原位
      const jumpHeight = Math.sin(progress * Math.PI) * (this.opponent?.isSpecialRooster ? 85 : 40);
      
      const targetPx = this.opponent?.isSpecialRooster ? (ex - 12) : (ex - 45);
      // 水平位置：前冲后回弹
      const forwardFactor = Math.sin(progress * Math.PI);
      px = basePx + (targetPx - basePx) * forwardFactor;
      py = basePy - jumpHeight;
    }

    if (isPlayerFlinching) px -= 12;

    if (this.isVictoryPosture) {
      px = this.width * 0.35;
      py = this.height * 0.28;
    }

    // 绘制玩家小促织
    this.drawPlayerCricket(ctx, px, py, isPlayerFlinching, isAttacking);

    if (this.touchStraw.active) {
      this.drawInteractiveStraw(ctx, this.touchStraw.x, this.touchStraw.y);
    }
  }

  drawChildShadowMetaphor(ctx) {
    ctx.save();
    ctx.translate(this.width * 0.22, this.height * 0.44);
    const flicker = 0.05 + Math.sin(this.tellCycle * 2) * 0.03;
    ctx.fillStyle = `rgba(180, 150, 100, ${flicker})`;

    ctx.beginPath();
    ctx.arc(0, -22, 10, 0, Math.PI * 2);
    ctx.ellipse(0, 0, 14, 18, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.strokeStyle = `rgba(180, 150, 100, ${flicker})`;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(8, -6);
    ctx.lineTo(20 + Math.sin(this.tellCycle * 3) * 6, -18);
    ctx.stroke();
    ctx.restore();
  }

  drawInteractiveStraw(ctx, x, y) {
    ctx.save();
    const isLateGame = this.currentOpponentIndex >= 2;
    ctx.strokeStyle = isLateGame ? "rgba(168, 56, 43, 0.9)" : "rgba(229, 185, 92, 0.75)";
    ctx.lineWidth = 3.5;
    ctx.lineCap = "round";
    ctx.beginPath();
    ctx.moveTo(x - 40, y + 25);
    ctx.quadraticCurveTo(x - 10, y + 5, x, y);
    ctx.stroke();
    ctx.restore();
  }

  drawPlayerCricket(ctx, x, y, isFlinching = false, isAttacking = false) {
    ctx.save();
    ctx.translate(x, y);

    const tellPhase = Math.sin(this.tellCycle);
    const isTellMoment = Math.abs(tellPhase) > 0.8;
    const headTilt = isTellMoment ? 0.14 : (this.isTeased ? -0.08 : 0);
    const legRub = isTellMoment ? Math.sin(this.tellCycle * 8) * 3 : 0;

    if (this.opponent?.isPalaceDance || this.isVictoryPosture) {
      ctx.rotate(Math.sin(this.tellCycle * 5) * 0.25);
    }

    if (isAttacking && this.opponent?.isSpecialRooster) {
      // 跃冠姿态：俯冲下咬
      ctx.rotate(0.4);
    }

    if (isFlinching) {
      ctx.fillStyle = "#ff4d4d";
      ctx.strokeStyle = "#8b0000";
    } else {
      ctx.fillStyle = "#485942";
      ctx.strokeStyle = "#1b241a";
    }
    ctx.lineWidth = 1.8;

    ctx.save();
    ctx.rotate(headTilt);
    ctx.beginPath();
    ctx.ellipse(-6, 0, 16, 8, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = isFlinching ? "#ff6666" : "#69593c";
    ctx.beginPath();
    ctx.ellipse(3, -3, 12, 5, -0.2, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();

    ctx.strokeStyle = isFlinching ? "#ffffff" : "#c49c48";
    ctx.beginPath();
    ctx.moveTo(10, -3);
    ctx.quadraticCurveTo(24, -16 + (isTellMoment ? 4 : 0), 38, -12);
    ctx.moveTo(10, 1);
    ctx.quadraticCurveTo(24, 14, 38, 10);
    ctx.stroke();
    ctx.restore();

    ctx.strokeStyle = isFlinching ? "#ff4d4d" : "#2b3327";
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(4, 4);
    ctx.lineTo(8 + legRub, 10);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(-12, 2);
    ctx.lineTo(-24, -14);
    ctx.lineTo(-28, 10);
    ctx.stroke();

    ctx.restore();
  }

  drawOpponent(ctx, x, y, isFlinching = false) {
    ctx.save();
    ctx.translate(x, y);

    if (this.enemyState === "dead") {
      ctx.rotate(Math.PI);
      ctx.translate(0, -15);
    }

    if (this.opponent?.isPalaceDance) {
      // 御前金案 · 金銮殿御座案几与锦缎
      ctx.fillStyle = "#8a2419";
      ctx.fillRect(-45, -28, 90, 20);
      ctx.fillStyle = "#e5b95c";
      ctx.fillRect(-40, -25, 80, 4);
      ctx.fillStyle = "#c49c48";
      ctx.fillRect(-35, -8, 70, 8);

      ctx.fillStyle = "#ffd700";
      ctx.font = "bold 12px var(--font-kai)";
      ctx.textAlign = "center";
      ctx.fillText("御 案", 0, -12);
    } else if (this.opponent?.isSpecialRooster) {
      // 抚军巨雄鸡
      if (this.enemyState === "windup") {
        ctx.fillStyle = "rgba(184, 59, 38, 0.45)";
        ctx.beginPath();
        ctx.arc(0, -40, 70, 0, Math.PI * 2);
        ctx.fill();
      }

      if (this.roosterImg.complete && this.roosterImg.naturalWidth > 0) {
        ctx.save();
        ctx.beginPath();
        ctx.arc(0, -45, 52, 0, Math.PI * 2);
        ctx.clip();
        if (isFlinching) ctx.filter = "brightness(1.5) sepia(1) hue-rotate(-50deg)";
        ctx.drawImage(this.roosterImg, -55, -100, 110, 110);
        ctx.restore();

        ctx.strokeStyle = this.enemyState === "windup" ? "#ff3300" : (isFlinching ? "#ffffff" : "#c49c48");
        ctx.lineWidth = this.enemyState === "windup" ? 4 : 2;
        ctx.beginPath();
        ctx.arc(0, -45, 52, 0, Math.PI * 2);
        ctx.stroke();
      } else {
        ctx.fillStyle = this.enemyState === "windup" ? "#8a281d" : "#2d241d";
        ctx.beginPath();
        ctx.ellipse(0, -30, 36, 54, 0, 0, Math.PI * 2);
        ctx.fill();
      }
    } else {
      if (this.enemyState === "windup") {
        ctx.fillStyle = "rgba(255, 51, 0, 0.4)";
        ctx.beginPath();
        ctx.arc(0, 0, 45, 0, Math.PI * 2);
        ctx.fill();
      }

      if (isFlinching) {
        ctx.fillStyle = "#ff4d4d";
        ctx.strokeStyle = "#ffffff";
      } else {
        ctx.fillStyle = this.enemyState === "windup" ? "#7e2218" : (this.enemyState === "stunned" ? "#444" : "#1f2420");
        ctx.strokeStyle = "#0d100e";
      }
      ctx.lineWidth = 2.5;

      ctx.beginPath();
      ctx.ellipse(0, 0, 26, 14, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();

      ctx.strokeStyle = this.enemyState === "windup" ? "#ff3300" : "#c49c48";
      const jawAngle = this.enemyState === "windup" ? 8 : (this.enemyState === "attack" ? 12 : 2);
      ctx.beginPath();
      ctx.moveTo(-22, -4);
      ctx.lineTo(-38, -jawAngle);
      ctx.moveTo(-22, 4);
      ctx.lineTo(-38, jawAngle);
      ctx.stroke();
    }

    ctx.restore();
  }

  stop() {
    this.isRunning = false;
    if (this.enemyActionTimer) clearTimeout(this.enemyActionTimer);
    if (this.danmuTimer) clearInterval(this.danmuTimer);
    if (this.animFrame) cancelAnimationFrame(this.animFrame);
  }
}
// 拍①：逼

function runBeat1(controller) {
  controller.updateSceneBg("scene-ruins");
  controller.setActors({ chengming: true, officer: true, wife: false, son: false });
  controller.setFortune(0, "大祸临头", "摊派催逼 · 杖责五十");
  
  const scripts = scriptData.beat1;
  let idx = 0;

  function showNext() {
    if (idx >= scripts.length) {
      controller.nextBeat();
      return;
    }
    const item = scripts[idx];
    controller.showDialog({
      kicker: item.kicker,
      speaker: item.speaker,
      text: item.text,
      btnText: item.action,
      onNext: () => {
        if (item.event === "cane_hit") {
          sound.playCaneHit();
          controller.flashScreen();
        }
        idx++;
        showNext();
      }
    });
  }

  showNext();
}
// 拍②：捕

function runBeat2(controller) {
  controller.updateSceneBg("scene-temple");
  controller.setActors({ chengming: true, wife: true, officer: false, son: false });
  controller.setFortune(15, "绝处求生", "得驼背巫画卷 · 寻虫古寺");

  const scripts = scriptData.beat2;
  let idx = 0;

  function showNext() {
    if (idx >= scripts.length) {
      controller.hideDialog();
      const catchLayer = document.getElementById("catch-layer");
      const catchGame = new CatchGame(catchLayer, () => {
        controller.nextBeat();
      });
      catchGame.start();
      return;
    }
    const item = scripts[idx];
    controller.showDialog({
      kicker: item.kicker,
      speaker: item.speaker,
      text: item.text,
      btnText: item.action,
      onNext: () => {
        idx++;
        showNext();
      }
    });
  }

  showNext();
}
// 拍③：养（物理掀盖透光＋亲手起名＋喂养互动＋二周目朱批）

function runBeat3(controller) {
  controller.updateSceneBg("scene-cottage");
  controller.setActors({ chengming: true, son: true, wife: true, officer: false, pot: true });
  controller.setFortune(30, "翻身有望", "得神虫青项金翅 · 悉心照护");

  if (storage.isSecondPlaythroughOrMore()) {
    controller.showMarginNote("朱批：得此神物，祸福倚伏……");
  }

  // 物理掀盖交互
  const pot = document.getElementById("prop-pot");
  if (pot) {
    pot.classList.add("can-open");
    pot.classList.remove("is-opened");
    if (!pot.querySelector(".pot-lid")) {
      pot.innerHTML = `
        <div class="pot-lid"></div>
        <div class="pot-light-beam"></div>
        <div class="pot-sprite"></div>
      `;
    }

    controller.showDialog({
      kicker: "【 案头密护 】",
      speaker: "成名",
      text: "置于陶盆之中，轻掩泥盖……（点按掀开瓦盖察视）",
      btnText: "掀开瓦盖",
      onNext: () => {
        openPotAndProceed();
      }
    });

    pot.onclick = (e) => {
      e.stopPropagation();
      openPotAndProceed();
    };
  } else {
    proceedWithScripts();
  }

  function openPotAndProceed() {
    if (pot) {
      pot.onclick = null;
      pot.classList.add("is-opened");
      pot.classList.remove("can-open");
    }
    sound.playLidOpen();
    sound.playBurstChirps(3);
    setTimeout(() => {
      proceedWithScripts();
    }, 600);
  }

  function proceedWithScripts() {
    const scripts = scriptData.beat3;
    let idx = 0;

    function showNext() {
      if (idx >= scripts.length) {
        controller.nextBeat();
        return;
      }
      const item = scripts[idx];

      if (item.event === "name_god_cricket") {
        controller.showDialogWithInput({
          kicker: item.kicker,
          speaker: item.speaker,
          text: item.text,
          defaultName: state.cricketName || "青项金翅",
          inputHint: "为这只神虫赐名：",
          btnText: "定下名号",
          onConfirm: (name) => {
            state.cricketName = name || "青项金翅";
            sound.playBurstChirps(2);
            idx++;
            showNext();
          }
        });
        return;
      }

      if (idx === 1) {
        controller.showFeedInteraction({
          kicker: item.kicker,
          speaker: item.speaker,
          text: item.text,
          maxFeed: 3,
          onFeedComplete: () => {
            idx++;
            showNext();
          }
        });
        return;
      }

      controller.showDialog({
        kicker: item.kicker,
        speaker: item.speaker,
        text: item.text,
        btnText: item.action,
        onNext: () => {
          if (item.tell) {
            sound.playChirp(0.2, 0.25);
          }
          idx++;
          showNext();
        }
      });
    }

    showNext();
  }
}
// 拍④：祸（盆覆儿亡 · 捡拾遗履 · 绝望拾小虫）

function runBeat4(controller) {
  controller.updateSceneBg("scene-cottage");
  controller.setActors({ chengming: true, son: false, wife: true, officer: false, pot: true, well: false });
  controller.setFortune(5, "家破人亡", "神虫毙 · 幼子失踪");

  if (storage.isSecondPlaythroughOrMore()) {
    controller.showMarginNote("朱批：痛极无言，何忍读之……");
  }

  const pot = document.getElementById("prop-pot");
  if (pot) {
    pot.classList.add("is-dead");
  }

  const scripts = scriptData.beat4;
  let idx = 0;

  function showNext() {
    if (idx >= scripts.length) {
      controller.nextBeat();
      return;
    }
    const item = scripts[idx];

    // 井沿场景拾起湿草鞋
    if (item.event === "well_scene") {
      controller.updateSceneBg("scene-well");
      controller.setActors({ chengming: true, wife: true, son: false, officer: false, pot: false, well: true });

      const shoe = document.querySelector(".wet-shoe");
      if (shoe) {
        shoe.classList.add("interactive");
        shoe.onclick = (e) => {
          e.stopPropagation();
          shoe.onclick = null;
          shoe.classList.remove("interactive");
          sound.playWaterDrop();
          controller.flashScreen();
          idx++;
          showNext();
        };
      }

      controller.showDialog({
        kicker: item.kicker,
        speaker: item.speaker,
        text: item.text,
        btnText: "拾起遗履",
        onNext: () => {
          sound.playWaterDrop();
          if (shoe) shoe.classList.remove("interactive");
          idx++;
          showNext();
        }
      });
      return;
    }

    // 黑场时间断点过渡
    if (item.event === "blackout_transition") {
      controller.hideDialog();
      controller.flashBlackout(() => {
        idx++;
        showNext();
      });
      return;
    }

    // 绝望中为羸弱小虫起名
    if (item.event === "name_small_cricket") {
      controller.updateSceneBg("scene-cottage");
      controller.setActors({ chengming: true, son: false, wife: true, officer: false, pot: true, well: false });
      if (pot) pot.classList.remove("is-dead");

      controller.showDialogWithInput({
        kicker: item.kicker,
        speaker: item.speaker,
        text: item.text,
        defaultName: state.smallCricketName || "小梅花",
        inputHint: "为这只瘦小促织起名：",
        btnText: "收存入盆",
        onConfirm: (name) => {
          state.smallCricketName = name || "小梅花";
          sound.playBurstChirps(2);
          idx++;
          showNext();
        }
      });
      return;
    }

    controller.showDialog({
      kicker: item.kicker,
      speaker: item.speaker,
      text: item.text,
      btnText: item.action,
      onNext: () => {
        idx++;
        showNext();
      }
    });
  }

  showNext();
}
// 拍⑤：斗/献/舞（四场阶梯战役单实例精密流转）

function runBeat5(controller) {
  controller.updateSceneBg("scene-court");
  controller.setActors({ chengming: false, wife: false, son: false, officer: false, pot: false, well: false });
  controller.hideDialog();

  // 清空本局战绩
  state.battleLog = [];

  const battleLayer = document.getElementById("battle-layer");
  battleLayer.hidden = false;

  let currentMatch = 0;
  let battleGame = new BattleGame({
    particleEngine: controller.particleEngine,
    onVictory: (opp, idx) => {
      // 记录战绩
      state.addBattleRecord({
        title: opp.title,
        oppName: opp.name,
        reward: opp.reward,
        rewardText: opp.rewardText
      });

      const newFortune = Math.min(100, 30 + (currentMatch + 1) * 20);
      controller.setFortune(newFortune, "如日中天", opp.rewardText);

      currentMatch++;

      if (currentMatch < opponentsData.length) {
        if (currentMatch === 2) {
          // 第2场（县衙巨甲）打赢后，必须进行案头研药调理备战大公鸡
          setTimeout(() => {
            showConditioningBeforeBoss(() => {
              battleGame.startMatch(currentMatch);
            });
          }, 600);
        } else {
          setTimeout(() => {
            battleGame.startMatch(currentMatch);
          }, 800);
        }
      } else {
        // 全部4场完成，进入拍⑥
        setTimeout(() => {
          battleGame.stop();
          battleLayer.hidden = true;
          controller.nextBeat();
        }, 1200);
      }
    },
    onDefeat: (opp, idx) => {
      controller.setFortune(Math.max(10, state.fortune - 10), "战绩受挫", "虫伤了，败绩若传开全家难保");
    }
  });

  function showConditioningBeforeBoss(onReady) {
    let modal = document.getElementById("rescue-modal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "rescue-modal";
      modal.className = "rescue-modal";
      document.body.appendChild(modal);
    }
    modal.hidden = false;

    let step = 0;
    const maxStep = 3;

    modal.innerHTML = `
      <div class="rescue-box">
        <h4 style="color:#c49c48;">【 案头研药 · 调理神虫 】</h4>
        <p id="rescue-desc">连胜两阵，小虫甲壳微损。明日将入抚军府与巨雄鸡生死一决……成名取清露草药，细细研磨敷治！</p>
        <div class="rescue-progress"><div class="rescue-fill" id="rescue-fill" style="background:#c49c48;"></div></div>
        <button class="rescue-action-btn" id="btn-do-rescue" type="button" style="background:#c49c48;">研磨药草（点按 0/3）</button>
      </div>
    `;

    const btn = document.getElementById("btn-do-rescue");
    const fill = document.getElementById("rescue-fill");
    const desc = document.getElementById("rescue-desc");

    btn.onclick = (e) => {
      e.stopPropagation();
      step++;
      sound.playWaterDrop();
      sound.vibrate(25);

      if (fill) fill.style.width = ((step / maxStep) * 100) + "%";
      if (btn) btn.innerText = `研磨敷治（点按 ${step}/${maxStep}）`;

      if (step >= maxStep) {
        sound.playBurstChirps(3);
        sound.vibrate([40, 50, 100]);
        if (desc) desc.innerHTML = `<span style="color:#c49c48;font-weight:bold;">金翅华彩大盛，神虫精力充盈！</span><br><small style="color:#555;">成名拜祷：“明日斗大公鸡，全仗神物神威！”</small>`;
        btn.innerText = "【 入抚军府迎战巨鸡 】";
        btn.style.background = "#a8382b";
        btn.onclick = (ev) => {
          ev.stopPropagation();
          modal.remove();
          if (onReady) onReady();
        };
      }
    };
  }

  // 开始第1场对决
  battleGame.startMatch(0);
}
// 拍⑥：苏（照见机关 · 涟漪置换 · 唯一长按定案朱印 · 拒绝重复）

function runBeat6(controller) {
  controller.updateSceneBg("scene-court");
  controller.setActors({ chengming: true, son: true, wife: true, officer: false, pot: false, well: false });
  controller.setFortune(100, "富埒王侯", "恩荫子孙 · 家益富");

  if (storage.isSecondPlaythroughOrMore()) {
    controller.showMarginNote("朱批：天道何在？发苦之极！");
  }

  // 清除任何旧残留的印章和按钮
  document.querySelectorAll(".seal-affix-section, .vermilion-stamp-mark").forEach(el => el.remove());

  const scripts = scriptData.beat6;
  let idx = 0;

  function showNext() {
    if (idx >= scripts.length) {
      showAwakeningLedger();
      return;
    }
    const item = scripts[idx];

    controller.showDialog({
      kicker: item.kicker,
      speaker: item.speaker,
      text: item.text,
      btnText: item.action,
      onNext: () => {
        idx++;
        showNext();
      }
    });
  }

  function showAwakeningLedger() {
    controller.hideDialog();
    const overlay = document.getElementById("awakening-overlay");
    const recordsContainer = document.getElementById("ledger-records");
    const actionsContainer = document.querySelector(".summary-actions");

    if (!overlay || !recordsContainer) return;

    // 清理旧内容
    document.querySelectorAll(".seal-affix-section, .vermilion-stamp-mark").forEach(el => el.remove());

    overlay.hidden = false;
    recordsContainer.innerHTML = "";
    if (actionsContainer) actionsContainer.hidden = true;

    const records = state.battleLog;
    const playerAssigned = state.smallCricketName || "小梅花";

    records.forEach((rec, i) => {
      const row = document.createElement("div");
      row.className = "ledger-row";
      row.innerHTML = `
        <div class="ledger-row-title">第 ${i + 1} 场 · 胜【${rec.oppName}】</div>
        <div class="ledger-row-desc">获 ${rec.reward}</div>
        <div class="ledger-subject" id="subj-${i}">出战者：【${playerAssigned}】</div>
      `;
      recordsContainer.appendChild(row);
    });

    sound.playBurstChirps(2);

    setTimeout(() => {
      const totalRippleTime = records.length * 650 + 600;

      records.forEach((_, i) => {
        setTimeout(() => {
          const subjEl = document.getElementById(`subj-${i}`);
          if (subjEl) {
            subjEl.classList.add("replaced");
            subjEl.innerText = "出战者：成名之子（九岁）";
            sound.playPaperFlip();
            sound.vibrate(25);
          }
        }, i * 650);
      });

      setTimeout(() => {
        storage.incrementPlaythrough();

        // 唯一长按印泥定案交互
        showPressHoldSealInteraction(() => {
          if (actionsContainer) actionsContainer.hidden = false;

          const btnSave = document.getElementById("btn-save-card");
          const btnRestart = document.getElementById("btn-restart-game");

          if (btnSave) {
            btnSave.onclick = (e) => { e.stopPropagation(); controller.generateMomentCard(); };
          }
          if (btnRestart) {
            btnRestart.onclick = (e) => {
              e.stopPropagation();
              overlay.hidden = true;
              controller.restartGame();
            };
          }
        });
      }, totalRippleTime);
    }, 2000);
  }

  function showPressHoldSealInteraction(onStamped) {
    const quoteBox = document.getElementById("awakening-quote");
    if (!quoteBox) {
      if (onStamped) onStamped();
      return;
    }

    // 确保绝对唯一，先清空可能存在的印章
    document.querySelectorAll(".seal-affix-section, .vermilion-stamp-mark").forEach(el => el.remove());

    const sealSection = document.createElement("div");
    sealSection.className = "seal-affix-section";
    sealSection.innerHTML = `
      <div class="seal-hold-box" id="seal-hold-box">
        <button class="seal-affix-btn" id="seal-affix-btn" type="button">
          <span>长按钤印 · 定案</span>
        </button>
        <div class="seal-progress-bar"><div class="seal-progress-fill" id="seal-progress-fill"></div></div>
        <small style="color:#888;font-size:11px;">按住屏幕一秒，朱印浸透宣纸定案</small>
      </div>
    `;
    quoteBox.after(sealSection);

    const btn = document.getElementById("seal-affix-btn");
    const progressFill = document.getElementById("seal-progress-fill");
    let holdTimer = null;
    let holdProgress = 0;
    let isComplete = false;

    const startHold = (e) => {
      if (isComplete) return;
      e.preventDefault();
      holdProgress = 0;
      sound.vibrate(20);

      holdTimer = setInterval(() => {
        holdProgress += 10;
        if (progressFill) progressFill.style.width = holdProgress + "%";
        if (holdProgress % 30 === 0) sound.vibrate(15);

        if (holdProgress >= 100) {
          clearInterval(holdTimer);
          isComplete = true;
          sound.playInkBleed();

          // 仅替换为单个印记，不产生重复节点
          sealSection.innerHTML = `
            <div class="vermilion-stamp-mark">天子一跬步，皆关民命。</div>
          `;
          setTimeout(() => {
            if (onStamped) onStamped();
          }, 600);
        }
      }, 90);
    };

    const cancelHold = () => {
      if (isComplete) return;
      clearInterval(holdTimer);
      holdProgress = 0;
      if (progressFill) progressFill.style.width = "0%";
    };

    btn.addEventListener("mousedown", startHold);
    btn.addEventListener("touchstart", startHold, { passive: false });
    window.addEventListener("mouseup", cancelHold);
    window.addEventListener("touchend", cancelHold);
  }

  showNext();
}
// 《促织》游戏主控制器与生命周期入口 v3（千人千面藏书票＋3D立体声＋触觉引擎）


class GameController {
  constructor() {
    this.state = state;
    this.sound = sound;
    this.storage = storage;
    this.particleEngine = null;
    this.onDialogNext = null;
    this.typewriterTimer = null;
    this.beatNames = ["① 逼", "② 捕", "③ 养", "④ 祸", "⑤ 斗", "⑥ 苏"];
  }

  init() {
    const dustContainer = document.getElementById("dust-particles");
    this.particleEngine = new ParticleEngine(dustContainer);
    this.particleEngine.start();

    if (this.state.isSecondPlaythrough) {
      this.sound.isSecondPlaythrough = true;
    }

    this.bindHUD();
    this.updatePlaythroughBadge();

    window.addEventListener("touchstart", () => this.sound.resume(), { once: true });
    window.addEventListener("click", () => this.sound.resume(), { once: true });

    this.startBeat(1);
  }

  bindHUD() {
    const soundBtn = document.getElementById("sound-btn") || document.getElementById("btn-audio");
    const restartBtn = document.getElementById("restart-btn") || document.getElementById("btn-restart");
    const manualBtn = document.getElementById("manual-btn") || document.getElementById("btn-manual");
    const nextBtn = document.getElementById("btn-next") || document.getElementById("dialog-next-btn");
    const closeCardBtn = document.getElementById("btn-close-card");
    const narrativePanel = document.getElementById("narrative-panel");

    if (soundBtn) {
      soundBtn.onclick = (e) => {
        e.stopPropagation();
        const isEnabled = this.sound.toggle();
        soundBtn.innerText = isEnabled ? "声 鸣" : "声 静";
      };
    }

    if (manualBtn) {
      manualBtn.onclick = (e) => {
        e.stopPropagation();
        this.showCricketManual();
      };
    }

    if (restartBtn) {
      restartBtn.onclick = (e) => {
        e.stopPropagation();
        this.showRestartConfirm();
      };
    }

    if (nextBtn) {
      nextBtn.onclick = (e) => {
        e.stopPropagation();
        if (this.onDialogNext) {
          this.sound.playPaperFlip();
          this.onDialogNext();
        }
      };
    }

    if (narrativePanel) {
      narrativePanel.onclick = (e) => {
        if (e.target.tagName === "INPUT" || e.target.tagName === "BUTTON") return;
        if (this.onDialogNext) {
          this.sound.playPaperFlip();
          this.onDialogNext();
        }
      };
    }

    if (closeCardBtn) {
      closeCardBtn.onclick = (e) => {
        e.stopPropagation();
        const modal = document.getElementById("moment-card-modal");
        if (modal) modal.hidden = true;
      };
    }

    window.addEventListener("keydown", (e) => {
      if (e.key === " " || e.key === "Enter") {
        const dialogPanel = document.getElementById("narrative-panel");
        if (dialogPanel && !dialogPanel.hidden && this.onDialogNext) {
          if (document.activeElement?.tagName === "INPUT") return;
          e.preventDefault();
          this.sound.playPaperFlip();
          this.onDialogNext();
        }
      }
    });
  }


  showMarginNote(text) {
    const existing = document.querySelector('.vermilion-margin-note');
    if (existing) existing.remove();

    const note = document.createElement('div');
    note.className = 'vermilion-margin-note';
    note.innerText = text;
    document.body.appendChild(note);

    setTimeout(() => {
      note.style.transition = 'opacity 1s ease';
      note.style.opacity = '0';
      setTimeout(() => note.remove(), 1000);
    }, 4500);
  }

  showRestartConfirm() {
    let modal = document.getElementById("custom-modal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "custom-modal";
      modal.className = "custom-modal";
      document.body.appendChild(modal);
    }
    modal.hidden = false;
    modal.innerHTML = `
      <div class="modal-box">
        <h4>重翻此页？</h4>
        <p>重新自“① 逼”开始这一局的遭遇与翻身之旅。</p>
        <div class="modal-actions">
          <button class="hud-btn" id="modal-cancel">留下</button>
          <button class="hud-btn" id="modal-confirm" style="background:#a8382b;color:#fff;border-color:#a8382b;">重翻</button>
        </div>
      </div>
    `;

    document.getElementById("modal-cancel").onclick = () => { modal.hidden = true; };
    document.getElementById("modal-confirm").onclick = () => {
      modal.hidden = true;
      this.restartGame();
    };
  }

  showCricketManual() {
    let modal = document.getElementById("manual-modal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "manual-modal";
      modal.className = "manual-modal";
      document.body.appendChild(modal);
    }
    modal.hidden = false;

    const unlocked = this.storage.getUnlockedManual();
    let listHtml = "";

    opponentsData.forEach((opp) => {
      const isUn = unlocked.includes(opp.id);
      const imgSrc = isUn ? (opp.image || "data:image/jpeg;base64,") : "";
      listHtml += `
        <div class="manual-item ${isUn ? "" : "locked"}" style="display:flex;gap:10px;align-items:center;">
          ${isUn ? `<img src="${imgSrc}" style="width:54px;height:54px;object-fit:cover;border-radius:6px;border:1px solid #c49c48;box-shadow:0 2px 6px rgba(0,0,0,0.3);" />` : `<div style="width:54px;height:54px;background:rgba(0,0,0,0.1);border-radius:6px;display:flex;align-items:center;justify-content:center;color:#999;font-size:12px;">锁</div>`}
          <div style="flex:1;">
            <h5>${isUn ? opp.name : "？？？"} <small style="color:#a8382b;font-weight:normal;">${opp.title}</small></h5>
            <p style="margin-top:2px;">${isUn ? opp.description : "尚未在斗场相逢……"}</p>
          </div>
        </div>
      `;
    });

    modal.innerHTML = `
      <div class="manual-paper">
        <div class="manual-head">
          <span class="paper-seal">异史拾遗</span>
          <h3>促 织 谱</h3>
        </div>
        <div class="manual-list">${listHtml}</div>
        <div style="text-align:center;margin-top:14px;">
          <button class="hud-btn" id="manual-close-btn">合上虫谱</button>
        </div>
      </div>
    `;

    document.getElementById("manual-close-btn").onclick = () => { modal.hidden = true; };
    modal.onclick = (e) => {
      if (e.target === modal) modal.hidden = true;
    };
  }

  updatePlaythroughBadge() {
    const badge = document.getElementById("second-play-tag");
    if (badge) {
      badge.hidden = !this.state.isSecondPlaythrough;
    }
  }

  updateSceneBg(bgClass) {
    const bg = document.getElementById("stage-bg");
    if (bg) {
      bg.className = "stage-bg " + bgClass;
    }
  }

  setActors(actors = {}) {
    const map = {
      chengming: document.getElementById("actor-chengming"),
      wife: document.getElementById("actor-wife"),
      son: document.getElementById("actor-son"),
      officer: document.getElementById("actor-officer"),
      pot: document.getElementById("prop-pot"),
      well: document.getElementById("prop-well")
    };

    for (const key in map) {
      if (map[key]) {
        map[key].hidden = !actors[key];
      }
    }
  }

  setFortune(val, label, subtext) {
    this.state.updateFortune(val, label, subtext);
    const fill = document.getElementById("fortune-fill");
    const statusText = document.getElementById("fortune-status-text") || document.getElementById("fortune-tag");
    const sub = document.getElementById("fortune-subtext") || document.getElementById("fortune-desc");

    if (fill) fill.style.width = Math.max(5, this.state.fortune) + "%";
    if (statusText) statusText.innerText = this.state.fortuneLabel;
    if (sub) sub.innerText = this.state.fortuneSubtext;
  }

  showDialog({ kicker, speaker, text, btnText = "翻阅下一折", onNext }) {
    const panel = document.getElementById("narrative-panel");
    const kickerEl = document.getElementById("dialog-kicker");
    const speakerEl = document.getElementById("dialog-speaker");
    const contentEl = document.getElementById("dialog-content");
    const btn = document.getElementById("btn-next") || document.getElementById("dialog-next-btn");

    if (btn) {
      btn.innerText = btnText;
      btn.onclick = (e) => {
        e.stopPropagation();
        if (this.onDialogNext) {
          this.sound.playPaperFlip();
          this.onDialogNext();
        }
      };
    }

    if (!panel) return;
    panel.hidden = false;

    if (kickerEl) kickerEl.innerText = kicker || "";
    if (speakerEl) speakerEl.innerText = speaker || "";
    if (btn) btn.innerText = btnText;

    if (this.typewriterTimer) clearTimeout(this.typewriterTimer);
    if (contentEl) {
      contentEl.innerHTML = "<p id=dialog-text></p>";
      const textEl = document.getElementById("dialog-text");
      let i = 0;

      const typeNextChar = () => {
        if (i < text.length) {
          const char = text[i];
          textEl.innerText += char;
          i++;

          let delay = 22;
          if (["，", "、", "；"].includes(char)) delay = 90;
          else if (["。", "！", "？", "…"].includes(char)) delay = 150;

          this.typewriterTimer = setTimeout(typeNextChar, delay);
        }
      };

      typeNextChar();
    }

    this.onDialogNext = onNext;
  }

  showDialogWithInput({ kicker, speaker, text, defaultName, inputHint, btnText, onConfirm }) {
    const panel = document.getElementById("narrative-panel");
    const kickerEl = document.getElementById("dialog-kicker");
    const speakerEl = document.getElementById("dialog-speaker");
    const contentEl = document.getElementById("dialog-content");
    const btn = document.getElementById("btn-next") || document.getElementById("dialog-next-btn");

    if (!panel) return;
    panel.hidden = false;

    if (kickerEl) kickerEl.innerText = kicker || "";
    if (speakerEl) speakerEl.innerText = speaker || "";
    if (btn) btn.innerText = btnText;

    if (this.typewriterTimer) clearTimeout(this.typewriterTimer);
    if (contentEl) {
      contentEl.innerHTML = `
        <p style="margin-bottom:6px;">${text}</p>
        <div class="dialog-input-wrap">
          <input type="text" id="cricket-name-input" value="${defaultName}" placeholder="${inputHint}" maxlength="8" autocomplete="off" />
        </div>
      `;
    }

    this.onDialogNext = () => {
      const input = document.getElementById("cricket-name-input");
      const name = input ? input.value.trim() : defaultName;
      if (onConfirm) onConfirm(name || defaultName);
    };
  }

  showFeedInteraction({ kicker, speaker, text, maxFeed = 3, onFeedComplete }) {
    const panel = document.getElementById("narrative-panel");
    const kickerEl = document.getElementById("dialog-kicker");
    const speakerEl = document.getElementById("dialog-speaker");
    const contentEl = document.getElementById("dialog-content");
    const btn = document.getElementById("btn-next") || document.getElementById("dialog-next-btn");

    if (!panel) return;
    panel.hidden = false;

    if (kickerEl) kickerEl.innerText = kicker || "";
    if (speakerEl) speakerEl.innerText = speaker || "";
    if (btn) btn.innerText = "继续照料";

    let fedCount = 0;

    if (this.typewriterTimer) clearTimeout(this.typewriterTimer);
    if (contentEl) {
      contentEl.innerHTML = `
        <p style="margin-bottom:6px;">${text}</p>
        <div class="feed-bowl-wrap">
          <button class="feed-click-btn" id="feed-click-btn" type="button">喂一粒粟</button>
          <span class="feed-count-tip" id="feed-count-tip">点按喂养：0 / ${maxFeed}</span>
        </div>
      `;

      const feedBtn = document.getElementById("feed-click-btn");
      const feedTip = document.getElementById("feed-count-tip");

      feedBtn.onclick = (e) => {
        e.stopPropagation();
        fedCount++;
        sound.playChirp(0.18, 0.25);
        if (feedTip) feedTip.innerText = `点按喂养：${fedCount} / ${maxFeed}`;

        if (fedCount >= maxFeed) {
          feedBtn.disabled = true;
          feedBtn.innerText = "已喂饱";
          if (feedTip) feedTip.innerText = "小虫振须轻鸣，伏盆甚安。";
        }
      };
    }

    this.onDialogNext = () => {
      if (onFeedComplete) onFeedComplete();
    };
  }

  hideDialog() {
    const panel = document.getElementById("narrative-panel");
    if (panel) panel.hidden = true;
    this.onDialogNext = null;
  }

  flashScreen() {
    const stage = document.getElementById("stage-shell");
    if (!stage) return;
    const flash = document.createElement("div");
    flash.style.position = "absolute";
    flash.style.inset = "0";
    flash.style.background = "rgba(168, 56, 43, 0.45)";
    flash.style.zIndex = "40";
    flash.style.pointerEvents = "none";
    stage.appendChild(flash);
    setTimeout(() => flash.remove(), 250);
  }

  flashBlackout(onDone) {
    const stage = document.getElementById("stage-shell");
    if (!stage) return;
    const black = document.createElement("div");
    black.style.position = "absolute";
    black.style.inset = "0";
    black.style.background = "#0d0e0c";
    black.style.zIndex = "45";
    black.style.display = "flex";
    black.style.alignItems = "center";
    black.style.justifyContent = "center";
    black.style.color = "#8c826e";
    black.style.fontSize = "14px";
    black.style.fontFamily = "var(--font-kai)";
    black.style.letterSpacing = "3px";
    black.innerText = "数日过去 · 万念俱灰";
    stage.appendChild(black);

    setTimeout(() => {
      black.remove();
      if (onDone) onDone();
    }, 1800);
  }

  startBeat(beat) {
    this.state.setBeat(beat);
    this.updateBeatProgress(beat);

    if (beat === 1) runBeat1(this);
    else if (beat === 2) runBeat2(this);
    else if (beat === 3) runBeat3(this);
    else if (beat === 4) runBeat4(this);
    else if (beat === 5) runBeat5(this);
    else if (beat === 6) runBeat6(this);
  }

  nextBeat() {
    const next = this.state.currentBeat + 1;
    if (next <= 6) {
      this.startBeat(next);
    }
  }

  updateBeatProgress(beat) {
    const nodes = document.querySelectorAll(".beat-node");
    nodes.forEach((node) => {
      const b = parseInt(node.getAttribute("data-beat"), 10);
      if (b === beat) {
        node.classList.add("active");
        node.classList.remove("passed");
        node.innerText = this.beatNames[b - 1];
      } else if (b < beat) {
        node.classList.remove("active");
        node.classList.add("passed");
        node.innerText = this.beatNames[b - 1];
      } else {
        node.classList.remove("active");
        node.classList.remove("passed");
        node.innerText = `⓪ ?`.replace("⓪", ["①","②","③","④","⑤","⑥"][b-1]);
      }
    });
  }

  // 千人千面古籍藏书票导出海报（P4）
  generateMomentCard() {
    const canvas = document.getElementById("moment-canvas");
    const modal = document.getElementById("moment-card-modal");
    if (!canvas || !modal) return;
    modal.hidden = false;

    const playerAssigned = this.state.smallCricketName || "小梅花";
    const sealData = this.state.getSealTitle();

    const renderCard = (sigCanvas = null) => {
      const ctx = canvas.getContext("2d");
      const w = canvas.width;
      const h = canvas.height;

      ctx.fillStyle = "#f3ece1";
      ctx.fillRect(0, 0, w, h);

      ctx.strokeStyle = "#1a1a18";
      ctx.lineWidth = 4;
      ctx.strokeRect(18, 18, w - 36, h - 36);
      ctx.lineWidth = 1;
      ctx.strokeRect(24, 24, w - 48, h - 48);

      ctx.strokeStyle = "rgba(168, 56, 43, 0.5)";
      ctx.strokeRect(28, 28, 14, 14);
      ctx.strokeRect(w - 42, 28, 14, 14);
      ctx.strokeRect(28, h - 42, 14, 14);
      ctx.strokeRect(w - 42, h - 42, 14, 14);

      ctx.fillStyle = "#a8382b";
      ctx.fillRect(w - 88, 45, 48, 48);
      ctx.fillStyle = "#fff";
      ctx.font = "bold 22px STKaiti, serif";
      ctx.fillText("聊斋", w - 76, 78);

      ctx.strokeStyle = "#a8382b";
      ctx.lineWidth = 2;
      ctx.strokeRect(w - 180, 45, 80, 30);
      ctx.fillStyle = "#a8382b";
      ctx.font = "bold 15px STKaiti, serif";
      ctx.fillText(sealData.title, w - 172, 66);

      ctx.fillStyle = "#1a1a18";
      ctx.font = "bold 30px STSong, serif";
      ctx.fillText("促 织 · 藏书票", 45, 75);

      ctx.font = "13px STKaiti, serif";
      ctx.fillStyle = "#666";
      ctx.fillText(`宣德三年 · ${sealData.sub}`, 45, 106);

      ctx.strokeStyle = "rgba(168, 56, 43, 0.4)";
      ctx.beginPath();
      ctx.moveTo(45, 122);
      ctx.lineTo(w - 45, 122);
      ctx.stroke();

      ctx.font = "bold 16px STSong, serif";
      ctx.fillStyle = "#1a1a18";
      ctx.fillText("【家运翻身实录】", 45, 155);

      ctx.font = "14px STSong, serif";
      ctx.fillStyle = "#333";
      let y = 188;
      this.state.battleLog.forEach((rec, i) => {
        ctx.fillText(`${i + 1}. 胜【${rec.oppName}】—— 获 ${rec.reward}`, 50, y);
        ctx.fillStyle = "#a8382b";
        ctx.fillText(`   出战者：【${playerAssigned}】`, 50, y + 22);
        ctx.fillStyle = "#333";
        y += 50;
      });

      ctx.fillStyle = "#a8382b";
      ctx.font = "bold 14px STKaiti, serif";
      ctx.fillText(`—— 你唤它作【${playerAssigned}】，它是你儿子。`, 45, y + 15);

      ctx.fillStyle = "rgba(26, 26, 24, 0.05)";
      ctx.fillRect(45, y + 26, w - 90, 115);
      ctx.strokeStyle = "#1a1a18";
      ctx.strokeRect(45, y + 26, w - 90, 115);

      ctx.font = "italic 15px STKaiti, serif";
      ctx.fillStyle = "#1a1a18";
      ctx.fillText("“儿床上悠悠转醒，自陈曰：", 60, y + 58);
      ctx.fillText("我这些天……化作了一只促织，轻捷善斗。”", 75, y + 88);
      ctx.font = "12px STSong, serif";
      ctx.fillStyle = "#888";
      ctx.fillText("——《聊斋志异 · 促织》", w - 210, y + 115);

      if (sigCanvas) {
        ctx.drawImage(sigCanvas, w - 160, h - 85, 110, 50);
        ctx.font = "11px STKaiti, serif";
        ctx.fillStyle = "#a8382b";
        ctx.fillText("【亲笔画押】", w - 160, h - 90);
      }

      ctx.font = "12px STSong, serif";
      ctx.fillStyle = "#999";
      ctx.fillText("异史氏曰：天子一跬步，皆关民命。", 45, h - 35);

      const dataUrl = canvas.toDataURL("image/png");
      const imgEl = document.getElementById("moment-card-rendered-img");
      const downloadLink = document.getElementById("moment-download-link");
      if (imgEl) imgEl.src = dataUrl;
      if (downloadLink) downloadLink.href = dataUrl;
    };

    const canvasWrap = document.querySelector(".moment-card-canvas-wrap");
    if (canvasWrap) {
      canvasWrap.innerHTML = `
        <img src="" id="moment-card-rendered-img" class="moment-card-img" alt="促织实录" />
        <span class="moment-tip">长按上方图片可直接存储到相册</span>

        <div class="signature-box">
          <div class="signature-head">
            <span>✍️ 指尖亲笔手写画押（签下名号或画圈）：</span>
            <button class="hud-btn" id="sig-clear-btn" style="padding:1px 6px;font-size:10px;" type="button">重签</button>
          </div>
          <canvas id="signature-canvas" width="280" height="70"></canvas>
        </div>
        
        <div class="share-copy-box">
          <span class="share-text" id="share-text-content">我养了一整局的常胜蟋蟀，是我儿子。——《促织》【${sealData.title}】</span>
          <button class="copy-text-btn" id="btn-copy-share" type="button">复制文案</button>
        </div>

        <div class="moment-actions-row">
          <a href="#" id="moment-download-link" download="促织_藏书票实录.png" class="hud-btn" style="flex:1;text-align:center;text-decoration:none;display:inline-block;padding:8px 0;background:#a8382b;color:#fff;">下载图片</a>
          <button class="hud-btn close-card-btn" id="btn-close-card" style="flex:1;" type="button">收起</button>
        </div>
      `;

      renderCard();

      const sigCv = document.getElementById("signature-canvas");
      if (sigCv) {
        const sigCtx = sigCv.getContext("2d");
        sigCtx.strokeStyle = "#1a1a18";
        sigCtx.lineWidth = 2.8;
        sigCtx.lineCap = "round";
        sigCtx.lineJoin = "round";

        let isDrawing = false;

        const getPos = (e) => {
          const rect = sigCv.getBoundingClientRect();
          const clientX = e.touches ? e.touches[0].clientX : e.clientX;
          const clientY = e.touches ? e.touches[0].clientY : e.clientY;
          return { x: (clientX - rect.left) * (sigCv.width / rect.width), y: (clientY - rect.top) * (sigCv.height / rect.height) };
        };

        const startDraw = (e) => {
          e.preventDefault();
          isDrawing = true;
          const p = getPos(e);
          sigCtx.beginPath();
          sigCtx.moveTo(p.x, p.y);
          this.sound.vibrate(10);
        };

        const draw = (e) => {
          if (!isDrawing) return;
          e.preventDefault();
          const p = getPos(e);
          sigCtx.lineTo(p.x, p.y);
          sigCtx.stroke();
        };

        const endDraw = () => {
          if (isDrawing) {
            isDrawing = false;
            renderCard(sigCv);
          }
        };

        sigCv.addEventListener("mousedown", startDraw);
        sigCv.addEventListener("mousemove", draw);
        sigCv.addEventListener("mouseup", endDraw);
        sigCv.addEventListener("touchstart", startDraw, { passive: false });
        sigCv.addEventListener("touchmove", draw, { passive: false });
        sigCv.addEventListener("touchend", endDraw);

        document.getElementById("sig-clear-btn").onclick = () => {
          sigCtx.clearRect(0, 0, sigCv.width, sigCv.height);
          renderCard(null);
        };
      }

      document.getElementById("btn-close-card").onclick = () => { modal.hidden = true; };

      document.getElementById("btn-copy-share").onclick = (e) => {
        e.stopPropagation();
        const copyBtn = document.getElementById("btn-copy-share");
        const txt = `我养了一整局的常胜蟋蟀，是我儿子。——《促织》【${sealData.title}】`;
        navigator.clipboard?.writeText?.(txt).then(() => {
          if (copyBtn) copyBtn.innerText = "已复制！";
          setTimeout(() => { if (copyBtn) copyBtn.innerText = "复制文案"; }, 2000);
        }).catch(() => {
          alert(txt);
        });
      };
    }
  }

  restartGame() {
    this.state.reset();
    const pot = document.getElementById("prop-pot");
    if (pot) pot.classList.remove("is-dead");

    const overlay = document.getElementById("awakening-overlay");
    if (overlay) overlay.hidden = true;

    const modal = document.getElementById("moment-card-modal");
    if (modal) modal.hidden = true;

    const catchLayer = document.getElementById("catch-layer");
    if (catchLayer) catchLayer.hidden = true;

    const battleLayer = document.getElementById("battle-layer");
    if (battleLayer) battleLayer.hidden = true;

    this.updatePlaythroughBadge();
    this.startBeat(1);
  }
}

window.addEventListener("DOMContentLoaded", () => {
  const game = new GameController();
  game.init();
});

